def metric(data: pd.DataFrame) -> float:
    import numpy as np

    validity_order = [1, 5, 3, 0, 2, 4]

    consistent_count = 0
    conflict_count = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        if a_wins == b_wins:
            continue
        tally_pref = 0 if a_wins > b_wins else 1

        ttb_pref = -1
        for idx in validity_order:
            if a[idx] != b[idx]:
                ttb_pref = 0 if a[idx] > b[idx] else 1
                break

        if ttb_pref != -1 and tally_pref != ttb_pref:
            conflict_count += 1
            if row['response'] == tally_pref:
                consistent_count += 1

    if conflict_count == 0:
        return 0.5
    return float(consistent_count / conflict_count)

